export const baseUiPopoverTriggerClassName =
  "inline-flex items-center justify-center rounded-md border border-gray-200 bg-white px-3 py-2 text-sm font-medium text-gray-950 shadow-sm transition hover:bg-gray-50 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent-600";

export const baseUiPopoverRootClassName = "relative inline-block";

export const baseUiPopoverPanelClassName =
  "z-50 w-72 rounded-lg border border-gray-200 bg-white p-4 text-sm text-gray-700 shadow-lg";

export const baseUiPopoverBackdropClassName =
  "fixed inset-0 z-40 bg-transparent";

import { describe, expect, test } from "vitest";

import * as Popover from "./index";

describe("Base UI Popover registry view", () => {
  test("reuses the Foldkit Popover functional contract", () => {
    expect(Popover.init).toBeTypeOf("function");
    expect(Popover.update).toBeTypeOf("function");
    expect(Popover.view).toBeTypeOf("function");
    expect(Popover.baseUiPopoverPanelClassName).toContain("rounded-lg");
  });
});
